// Point-cloud binaries embedded inline as base64 so the viewer works from
// file:// without fetch/CORS. Generated by scripts/lab3/build_report_assets.py.
const PCDATA = {"3dgs_fps4": {"n": 50000, "label": "3DGS gaussians (fps4, 100k subsample)", "b64": ""}, "3dgs_fps8": {"n": 50000, "label": "3DGS gaussians (fps8, 80k subsample)", "b64": ""}, "nerf_sparse_fps4": {"n": 50000, "label": "Nerfacto sparse point cloud (fps4)", "b64": ""}, "neus_fps4": {"n": 50000, "label": "NeuS SDF mesh vertices (fps4)", "b64": ""}, "sfm_dense_fps5": {"n": 50000, "label": "COLMAP dense cloud (fps5, 100k subsample)", "b64": ""}};
const fallback = document.getElementById('pc-fallback');
const canvas = document.getElementById('viewer-canvas');
const info = document.getElementById('pc-info');
let THREE, renderer, scene, camera, controls, points = null, spin = true, raf = 0;
const INITIAL_DIST = 1.9;
const distEl = () => document.getElementById('pc-dist');

async function boot() {
  try {
    THREE = await import('three');
    const oc = await import('three/addons/controls/OrbitControls.js');
    renderer = new THREE.WebGLRenderer({canvas, antialias:true});
    renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
    scene = new THREE.Scene(); scene.background = new THREE.Color(0x111111);
    camera = new THREE.PerspectiveCamera(55, 16/9, 0.01, 1000); camera.position.set(0,0,INITIAL_DIST);
    controls = new oc.OrbitControls(camera, canvas);
    controls.enableDamping = true; controls.autoRotate = true; controls.autoRotateSpeed = 0.8;
    controls.zoomSpeed = 2.5;  // faster wheel zoom (default 1 was too slow)
    document.getElementById('pc-spin').addEventListener('change', e => controls.autoRotate = e.target.checked);
    document.getElementById('pc-reset').addEventListener('click', () => load(document.getElementById('pc-select').value));
    document.getElementById('pc-select').addEventListener('change', e => load(e.target.value));
    // distance slider: move camera along its current view direction
    distEl().addEventListener('input', e => {
      if (!controls) return;
      const d = parseFloat(e.target.value);
      const dir = new THREE.Vector3().subVectors(camera.position, controls.target);
      dir.normalize().multiplyScalar(d);
      camera.position.copy(controls.target).add(dir);
      controls.update();
    });
    // keep slider in sync with wheel/dolly zoom
    controls.addEventListener('change', () => {
      if (!distEl()) return;
      const d = camera.position.distanceTo(controls.target);
      if (Math.abs(d - parseFloat(distEl().value)) > 0.02) distEl().value = d.toFixed(2);
    });
    window.addEventListener('resize', resize); resize();
    load('3dgs_fps4'); animate();
  } catch (err) {
    console.error(err);
    canvas.style.display = 'none'; fallback.style.display = 'block';
    document.querySelectorAll('.viewer-bar button,.viewer-bar select,.viewer-bar input').forEach(e=>e.disabled=true);
  }
}

function resize(){
  const w = canvas.clientWidth, h = canvas.clientHeight;
  if (renderer) renderer.setSize(w, h, false);
  if (camera){ camera.aspect = w/h; camera.updateProjectionMatrix(); }
}

async function load(name){
  info.textContent = '加载 ' + name + ' …';
  const meta = PCDATA[name];
  if (!meta){ info.textContent = '缺少 ' + name; return; }
  // Decode embedded base64 (works on file:// too — no fetch/CORS).
  const bstr = atob(meta.b64);
  const buf = new ArrayBuffer(bstr.length);
  const view = new Uint8Array(buf);
  for (let i=0;i<bstr.length;i++) view[i] = bstr.charCodeAt(i);
  const n = meta.n;
  const xyz = new Float32Array(buf, 0, n*3);
  const rgb = new Uint8Array(buf, n*3*4, n*3);
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(xyz, 3));
  const colors = new Float32Array(n*3);
  for (let i=0;i<n*3;i++) colors[i] = rgb[i]/255;
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  // center + scale to unit sphere
  geo.computeBoundingSphere();
  const c = geo.boundingSphere.center, r = Math.max(geo.boundingSphere.radius, 1e-6);
  const pos = geo.attributes.position;
  for (let i=0;i<n;i++){ pos.setXYZ(i, (pos.getX(i)-c.x)/r, (pos.getY(i)-c.y)/r, (pos.getZ(i)-c.z)/r); }
  pos.needsUpdate = true;
  if (points){ scene.remove(points); points.geometry.dispose(); points.material.dispose(); }
  const mat = new THREE.PointsMaterial({size:0.012, vertexColors:true, sizeAttenuation:true});
  points = new THREE.Points(geo, mat);
  scene.add(points);
  camera.position.set(0,0,INITIAL_DIST); controls.target.set(0,0,0); controls.update();
  if (distEl()) distEl().value = String(INITIAL_DIST);
  info.textContent = meta.label + '  ·  ' + n + ' pts';
}

function animate(){
  raf = requestAnimationFrame(animate);
  if (controls) controls.update();
  if (renderer && scene && camera) renderer.render(scene, camera);
}

boot();
